class Solution
{
public:
    int maxKilledEnemies(vector<vector<char>>& grid)
    {
        if (grid.empty() || grid[0].empty()) return 0;
        int m = grid.size(), n = grid[0].size();
        vector<int> colHits(n, 0);
        int rowHits = 0, best = 0;
        for (int r = 0; r < m; ++r)
        {
            for (int c = 0; c < n; ++c)
            {
                if (c == 0 || grid[r][c - 1] == 'W')
                {
                    rowHits = 0;
                    for (int j = c; j < n && grid[r][j] != 'W'; ++j)
                    {
                        if (grid[r][j] == 'E') ++rowHits;
                    }
                }
                if (r == 0 || grid[r - 1][c] == 'W')
                {
                    colHits[c] = 0;
                    for (int i = r; i < m && grid[i][c] != 'W'; ++i)
                    {
                        if (grid[i][c] == 'E') ++colHits[c];
                    }
                }
                if (grid[r][c] == '0')
                {
                    best = max(best, rowHits + colHits[c]);
                }
            }
        }
        return best;
    }
};
